WITH transactions_by_account AS (SELECT account_id, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list, SUM(CASE WHEN merchant = 'Shell' THEN 1 ELSE 0 END) AS shell_count FROM transactions GROUP BY account_id) SELECT a.id, a.customer_id, a.status, tba.txn_type_list, tba.shell_count FROM accounts a INNER JOIN transactions_by_account tba ON a.id = tba.account_id ORDER BY a.customer_id ASC, id ASC LIMIT 1;
